mapper.select:
SELECT kg_student.id `id`, kg_student.NAME `name`, kg_student.gender `gender`, kg_student.is_weak `isWeak`, kg_student.special_case `specialCase`, kg_student.real_img_url `realImgUrl`, kg_student.update_time `updateTime`, kg_classroom.class_name, temp.`name` guardianName, temp.phone guardianPhone FROM kg_student LEFT JOIN kg_classroom ON kg_student.class_id = kg_classroom.id LEFT JOIN ( SELECT student_id, GROUP_CONCAT( NAME ) NAME, GROUP_CONCAT( phone ) phone FROM kg_guardian WHERE kg_id = #{queryVO.kgId} GROUP BY student_id ) temp ON temp.student_id = kg_student.id WHERE kg_student.del_flag = 0 AND kg_student.kg_id = #{queryVO.kgId}
AND kg_classroom.id = #{queryVO.classId}
AND kg_student.is_weak = #{queryVO.isWeak}
AND (kg_student.real_img_url IS NOT NULL AND kg_student.real_img_url != '')
AND (kg_student.real_img_url IS NULL OR kg_student.real_img_url = '')
AND kg_student.is_leave_school = 0
AND ( temp.`name` LIKE concat('%', #{queryVO.info}, '%') OR temp.phone LIKE concat('%', #{queryVO.info}, '%') OR kg_student.NAME LIKE concat('%', #{queryVO.info}, '%') )
ORDER BY kg_student.create_time DESC
